from typing import List

def validateBinaryTreeNodes(n: int, leftChild: List[int], rightChild: List[int]) -> bool:
    parents = [-1] * n
    for i in range(n):
        for child in [leftChild[i], rightChild[i]]:
            if child != -1:
                if parents[child] != -1:
                    return False
                parents[child] = i
    root_count = sum(1 for p in parents if p == -1)
    if root_count != 1:
        return False
    visited = [False] * n
    stack = [i for i, p in enumerate(parents) if p == -1]
    while stack:
        node = stack.pop()
        if visited[node]:
            return False
        visited[node] = True
        for child in [leftChild[node], rightChild[node]]:
            if child != -1:
                stack.append(child)
    return all(visited)
